{"script":"() => {
  // Try to find the count of results shown in the sidebar
  const resultsSection = document.querySelector('[aria-label*="结果"], [aria-label*="results"]');

  // Look for elements containing "results" or count info
  const countElements = Array.from(document.querySelectorAll('*')).filter(el => {
    const text = el.textContent;
    return text && text.match(/^[^\d]*\d+[^\d]*$/) && el.children.length === 0;
  }).map(el => ({text: el.textContent.trim(), tag: el.tagName}));

  // Find all the Target results in the sidebar list
  const targetLinks = document.querySelectorAll('a[aria-label="Target"]');

  // Find text containing "结果" (Results) or counts
  const countTexts = [];
  document.querySelectorAll('div, span').forEach(el => {
    const text = el.textContent.trim();
    if (text === '结果' || text.includes('个结果') || text.includes('搜索结果') || text.match(/^\d+ 个/)) {
      countTexts.push({text: text, parents: el.parentElement?.textContent?.trim()?.substring(0, 200)});
    }
  });

  return {
    targetCount: targetLinks.length,
    countElements: countElements.slice(0, 20),
    countTexts: countTexts.slice(0, 20)
  };
}"}

