{"script":"() => {
  // Look for "result count" text in results panel
  const allText = document.body.innerText;

  // Try to find numbers that might indicate result count
  const matches = allText.match(/\d+\s*[\u4e00-\u9fff]*\u7ed3\u679c[\u4e00-\u9fff]*/g);

  // Also count Target entries
  const allLinks = document.querySelectorAll('a, div');
  let targetCount = 0;
  allLinks.forEach(el => {
    if (el.textContent.trim() === 'Target' || (el.getAttribute && el.getAttribute('aria-label') === 'Target')) {
      targetCount++;
    }
  });

  // Find header text
  const headers = [];
  document.querySelectorAll('h1, h2, h3, [class*="header"], [class*="title"]').forEach(el => {
    headers.push({text: el.textContent.trim(), tag: el.tagName});
  });

  // Find result count specific elements
  const resultHeaders = [];
  document.querySelectorAll('div, span').forEach(el => {
    const text = el.textContent;
    if (el.children.length === 0 && text && (text.includes('结果') || text.includes('个地点'))) {
      resultHeaders.push({text: text.trim().substring(0, 100), ariaLabel: el.getAttribute('aria-label')});
    }
  });

  return {
    targetCount: targetCount,
    resultHeaders: resultHeaders.slice(0, 20),
    matches: matches ? matches.slice(0, 10) : []
  };
}"}

