{"script":"() => {
  // Look for all links/buttons labeled "Target" in the results panel
  const allElements = document.querySelectorAll('a[aria-label="Target"]');

  // Also count items in the scrollable results container
  const resultContainers = document.querySelectorAll('[role="main"], [aria-label*="结果"], div');
  let resultsContainer = null;
  for (const div of resultContainers) {
    if (div.getAttribute('aria-label') && div.getAttribute('aria-label').includes('结果')) {
      resultsContainer = div;
      break;
    }
  }

  // Count anchors with Target label
  let targetCount = allElements.length;

  // Try to find the visible count in the heading
  const headings = document.querySelectorAll('div');
  let headingText = '';
  for (const h of headings) {
    const txt = h.textContent.trim();
    if (txt === '结果' || txt.includes('结果')) {
      headingText = h.textContent;
      break;
    }
  }

  // Get all star rating spans to verify each entry has one
  const starRatings = document.querySelectorAll('span[role="img"][aria-label*="星级"]');

  // Count how many entries have ratings visible
  const entriesWithRatings = {};
  starRatings.forEach(s => {
    const text = s.getAttribute('aria-label');
    entriesWithRatings[text] = (entriesWithRatings[text] || 0) + 1;
  });

  return {
    targetAnchorCount: targetCount,
    starRatingCount: starRatings.length,
    starRatings: Object.entries(entriesWithRatings),
    headingText: headingText
  };
}"}

